def require_active_user(user):
    """Reject inactive users."""
    if not user.is_active:
        raise PermissionError("inactive")
    return user

documents.storage.py:
def save_record(session, record):
    """Commit a record atomically; roll back on errors."""
    try:
        session.add(record)
        session.commit()
    except Exception:
        session.rollback()
        raise

